#Generated by Claude to use qwen local model to classify Gmail messages into labels.
import json
import ollama
from google.auth.transport.requests import Request
from google.oauth2.credentials import Credentials
from google_auth_oauthlib.flow import InstalledAppFlow
from googleapiclient.discovery import build

SCOPES = ["https://www.googleapis.com/auth/gmail.modify"]
LABELS = ["College Admissions", "Receipts", "LinkedIn", "Promotions",
          "News", "Security", "Other"]
MODEL = "qwen3.5:4b"      # or "qwen3.5:2b"
BATCH = 1000
DRY_RUN = False           # print decisions only; set False to actually label

stats = {"tokens": 0, "ns": 0, "calls": 0}   # accumulated across classify() calls

def get_service():
    creds = None
    try:
        creds = Credentials.from_authorized_user_file("token.json", SCOPES)
    except FileNotFoundError:
        pass
    if not creds or not creds.valid:
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        else:
            flow = InstalledAppFlow.from_client_secrets_file("credentials.json", SCOPES)
            creds = flow.run_local_server(port=0)
        with open("token.json", "w") as f:
            f.write(creds.to_json())
    return build("gmail", "v1", credentials=creds)

def label_ids(svc):
    labels = svc.users().labels().list(userId="me").execute()["labels"]
    by_name = {l["name"]: l["id"] for l in labels}
    missing = [n for n in LABELS if n not in by_name]
    if missing:
        raise SystemExit(f"Create these labels in Gmail first: {missing}")
    return {n: by_name[n] for n in LABELS}

def header(msg, name):
    for h in msg["payload"]["headers"]:
        if h["name"].lower() == name.lower():
            return h["value"]
    return ""

def classify(sender, subject, snippet):
    prompt = (
    "Classify this email into exactly one label.\n\n"
    "Labels:\n"
    "- College Admissions: ONLY from an actual college or university (admissions offices, "
    "open houses, application or document reminders, invitations from the school itself, "
    "and current staff such as Fordham admissions counselors). "
    "NOT from scholarship companies, tutoring or test-prep companies, college-prep platforms, "
    "College Board, third-party college-search sites such as Discovering U.org, "
    "Instructure or Canvas, or organizations like Science Olympiad.\n"
    "- Receipts: order confirmations, payment receipts, shipping or purchase records.\n"
    "- LinkedIn: anything from linkedin.com.\n"
    "- Promotions: stores, restaurants, pharmacies (including Walgreens), product marketing, "
    "sales, coupons, surveys from businesses, job-alert marketing, Encourage, Google Gemini "
    "marketing, Schoolhouse.world and other tutoring or test-prep marketing, Test Ninjas, "
    "Niche, BigFuture and other College Board marketing, Kroger, and marketing from companies "
    "selling courses or scholarship services.\n"
    "- News: newsletters and digests (for example Quora Digest, Samsung news, Fill it Forward, "
    "Alliance Francaise newsletters, RECF Newsletter, SAT feedback surveys).\n"
    "- Security: sign-in, password-change, sign-on, security, verification, or account-deletion "
    "alerts from Google, Microsoft, Meta, Samsung, Discord, Coinbase, OpenEDG, College Board "
    "sign-on notifications, or banks such as Chase.\n"
    "- Other: personal emails from individuals, GitHub, Google Docs or Drive notifications, "
    "carrier or service notices, badges and certificates, work or internship meetings and "
    "calendar invitations, Schoolhouse.world bulletins, Khan Academy progress, Facebook and "
    "social notifications, volunteer and program allocation notices, account setup or "
    "device-setup confirmations, background-check notices (Bchex, My Background Check), SAT and AP "
    "exam notices and score reports, and anything that fits no other label.\n\n"
    "Examples:\n"
    "- 'ScholarshipOwl: Thinking about ScholarshipOwl?' -> Promotions\n"
    "- 'Beaver-Edge AI Institute: Remodeled AI Olympiad courses' -> Promotions\n"
    "- 'Schoolhouse.world: New Announcement in SAT Bootcamp Tutors' -> Promotions\n"
    "- 'Schoolhouse Bulletin: What's new this week?' -> Other\n"
    "- 'Boston College admissions: How will you excel?' -> College Admissions\n"
    "- 'Fordham staff member: Atul, why did I choose Fordham?' -> College Admissions\n"
    "- 'Science Olympiad: 2027 Division C Rules Manual' -> Other\n"
    "- 'Instructure Canvas: Canvas resources' -> Other\n"
    "- 'Discovering U.org: Join UChicago, Columbia...' -> Promotions\n"
    "- 'Total Wireless: Time's up! Your service is about to end.' -> Other\n"
    "- 'Panera Bread: Atul, tell us what you think.' -> Promotions\n"
    "- 'Walgreens: Safety first! But after that, let's talk about savings.' -> Promotions\n"
    "- 'Google Gemini: Make impossible selfies with Gemini' -> Promotions\n"
    "- 'Google: Atul, finish setting up your Apple iPhone' -> Other\n"
    "- 'Chase: You received money with Zelle' -> Security\n"
    "- 'College Board: New sign-on notification' -> Security\n"
    "- 'OpenEDG: Password Change Request' -> Security\n"
    "- 'SAT: Your Digital SAT Scores Are Now Available' -> Other\n"
    "- 'BigFuture: Atul's September Rundown' -> Promotions\n"
    "- 'My Background Check: Bchex Application In Progress' -> Other\n"
    "- 'Joshua Iglesia: Invitation: Appstle Introduction Call' -> Other\n"
    "- 'Facebook: Security alert: new login to your account' -> Security\n"
    "- 'LinkedIn: You appeared in 4 searches' -> LinkedIn\n\n"
    "Rules:\n"
    "- Choose the label that best matches the sender's purpose, not the topic of the subject line.\n"
    "- Use College Admissions only when the sender is the college or university itself, or one of its staff.\n"
    "- If unsure, choose Other.\n\n"
    f"From: {sender}\nSubject: {subject}\nSnippet: {snippet[:300]}"
)

    resp = ollama.chat(
        model=MODEL,
        messages=[{"role": "user", "content": prompt}],
        format={"type": "object",
                "properties": {"label": {"enum": LABELS}},
                "required": ["label"]},
        think=False,
        options={"temperature": 0, "num_ctx": 4096},
        keep_alive="30m",
    )
    stats["tokens"] += resp.eval_count or 0
    stats["ns"] += resp.eval_duration or 0
    stats["calls"] += 1
    return json.loads(resp.message.content)["label"]

def print_speed():
    if not stats["ns"]:
        print("\nNo model calls made; no tokens/sec to report.")
        return
    secs = stats["ns"] / 1e9
    print(f"\n{MODEL}: {stats['tokens']} output tokens over {stats['calls']} calls "
          f"in {secs:.2f}s generation time -> {stats['tokens'] / secs:.2f} avg output tokens/sec")

def main():
    svc = get_service()
    ids = label_ids(svc)
    threads = []
    page_token = None
    while len(threads) < BATCH:
        resp = svc.users().threads().list(
            userId="me", q="in:inbox",
            maxResults=min(500, BATCH - len(threads)),
            pageToken=page_token,
        ).execute()
        threads.extend(resp.get("threads", []))
        page_token = resp.get("nextPageToken")
        if not page_token:
            break

    if not threads:
        print("Inbox is empty.")
        return

    for t in threads:
        thread = svc.users().threads().get(
            userId="me", id=t["id"], format="metadata",
            metadataHeaders=["From", "Subject"]
        ).execute()
        msg = thread["messages"][-1]
        sender = header(msg, "From")
        subject = header(msg, "Subject")
        if sender.lower().endswith("linkedin.com>") or "@linkedin.com" in sender.lower():
            label = "LinkedIn"
        elif "schoolhouse" in sender.lower() and "bulletin" not in subject.lower():
            label = "Promotions"
        elif "facebook" in sender.lower() and ("notification" in subject.lower() or "others" in subject.lower()):
            label = "Other"
        elif "google" in sender.lower() and any(k in subject.lower() for k in ["security alert", "sign-in", "sign in", "password", "recovery", "verify", "account data"]):
            label = "Security"
        else:
            label = classify(sender, subject, msg.get("snippet", ""))
        print(f"{label:18} | {sender[:40]:40} | {subject[:60]}")

        if not DRY_RUN:
            svc.users().threads().modify(
                userId="me", id=t["id"],
                body={"addLabelIds": [ids[label]], "removeLabelIds": ["INBOX"]},
            ).execute()

    print_speed()

if __name__ == "__main__":
    main()